"""Build a reviewable report from recorded outcomes; never infer a rendered pass from a mesh."""
import argparse
import collections
import datetime
import html
import json
import xml.etree.ElementTree as ET
from pathlib import Path

parser = argparse.ArgumentParser()
parser.add_argument("results", type=Path)
parser.add_argument("--output", type=Path, default=Path("docs/qa/ruhi-graph-evidence"))
args = parser.parse_args()
data = json.loads(args.results.read_text(encoding="utf-8"))
results = data["results"]
assert len({item["id"] for item in results}) == len(results), "Duplicate test IDs"
args.output.mkdir(parents=True, exist_ok=True)
(args.output / "results.json").write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding="utf-8")
categories = ["Object Creation", "Delete & Reset", "Positioning", "Scaling", "Rotation", "Appearance", "3D Graphing", "Geometry Relations", "Conversational AI", "Error & Stress Tests"]
counts = collections.Counter(item["status"] for item in results)
recorded_ids = {item["id"] for item in results}
missing = sorted(set(range(1, 151)) - recorded_ids)
lines = ["# Ruhi — native 2D and 3D Graph audit", "", "Recorded on " + datetime.datetime.now(datetime.timezone(datetime.timedelta(hours=5, minutes=30))).isoformat(timespec="seconds"), "", "This is the Android/Kotlin AIExplorer application. This uses native meshes and a bundled TensorFlow-trained intent classifier with LiteRT; it does not use Three.js. Results describe graph layers and native CPU-projected canvas pixels, not WebGL/GPU certification. Unsupported results are capability gaps, not passes.", "", "| Test Category | Total | Passed | Failed | Unsupported |", "|---|---:|---:|---:|---:|"]
for category, total in zip(categories, [20, 10] + [15] * 8):
    c = collections.Counter(item["status"] for item in results if item["category"] == category)
    lines.append(f"| {category} | {total} | {c['PASSED']} | {c['FAILED']} | {c['UNSUPPORTED']} |")
lines.extend([f"| **Total** | **150** | **{counts['PASSED']}** | **{counts['FAILED']}** | **{counts['UNSUPPORTED']}** |", "", f"Rendering skipped: {counts['SKIPPED_RENDERING']}. Unrecorded IDs: {missing or 'none'}.", ""])
if counts['SKIPPED_RENDERING']:
    lines.extend(["**Verification remains incomplete:** at least one supported case has no valid canvas capture. A passing instrumentation method does not promote skipped cases to passes.", ""])
state_verified=sum(not item["errors"] and item["execution"]!="UNSUPPORTED" for item in results)
lines.extend([f"Scene/geometry checks verified: {state_verified}. Applied scene operations: {sum(item['execution']=='APPLIED' for item in results)}. Safe invalid-input rejections: {sum(item['execution']=='INVALID' for item in results)}. Requests for missing numeric arguments: {sum(item['execution']=='CLARIFICATION' for item in results)}. State/mesh verification is tracked separately from rendering.", ""])
if not any(item["rendering"]!="NOT_RUN" for item in results):
    lines.extend(["**Visual verification is blocked.** No successful canvas evidence is present in this input. Earlier emulator/service and corrupt APK failures are retained as infrastructure history. No command is promoted to a full pass without its rendering assertion. See infrastructure evidence. The task's full completion criteria have not been met.", ""])
test_xml=[ET.parse(path).getroot() for path in args.output.glob("TEST-*.xml")]
if test_xml:
    lines.extend([f"Regression JUnit tests recorded: {sum(int(item.get('tests',0)) for item in test_xml)}; failures: {sum(int(item.get('failures',0))+int(item.get('errors',0)) for item in test_xml)}.", ""])
supported = [item for item in results if item["expected_intent"] not in ("UNSUPPORTED", "INVALID", "CLARIFICATION")]
parser_correct = sum(bool(item["actual_parser"]) and f"intent={item['expected_intent']}" in item["actual_parser"][0] for item in supported)
execution_correct = sum(not item["errors"] and item["execution"] == "APPLIED" for item in supported)
rendered = [item for item in results if item["rendering"] != "NOT_RUN"]
context = [item for item in supported if item["id"] in {23,27,82,88,89,90,119,121,124,127,129,133,134,145,146}]
two_d = args.output / "device" / "2d-ask-result.json"
if two_d.exists():
    evidence = json.loads(two_d.read_text(encoding="utf-8"))
    lines.extend([f"- Supplemental 2D visible-prompt test: {'PASS' if evidence.get('passed') else 'FAIL'}; changed canvas pixels: {evidence.get('changed_canvas_pixels')}."])
lines.extend(["- Device configuration and exact build/model hashes are recorded in device-config.json and source-manifest.json. Previous timeout evidence is archived under baseline-2026-10-15."])
nlp_path=args.output/"nlp-evaluation.json"
if nlp_path.exists():
    nlp=json.loads(nlp_path.read_text(encoding="utf-8"))
    lines.extend([f"- TensorFlow exported-model development intent evaluation: {nlp['correct']}/{nlp['total']} authored sentences excluded from training. Inspected during development; this does not establish unrestricted language understanding. See ../ruhi-nlp-command-training/REPORT.md for the current requested-command replay and separate evaluation."])

lines.extend(["## Evidence provenance", "", "The 120-pass/30-unsupported pixel results below are the retained successful full replay, not a claim that the final delivery emulator recheck completed. The final recheck encountered intermittent capture skips and then emulator startup ANRs/storage permission failures. See intermittent-capture-before-redraw and device-full-run.log. Current source/model hashes and 61 passing JVM regressions are recorded separately. The new native display-crop capture helper compiled, but its complete device replay remains unverified.", ""])
lines.extend([f"- Supported-case parser checks: {parser_correct}/{len(supported)}. This excludes unsupported sentences and is not an assertion of general English accuracy.", f"- Supported execution checks: {execution_correct}/{len(supported)}.", f"- Render assertions: {sum(item['rendering']=='PASS' for item in rendered)}/{len(rendered)}; includes unchanged-canvas checks on rejected instructions. Pixel comparison uses the central plot area to exclude overlapping chrome/status text. The 150-case audit captures the Android display and crops to measured canvas bounds, avoiding Compose PixelCopy redraw timeouts; missing captures remain rendering skipped.", f"- Supported context checks: {sum(not item['errors'] for item in context)}/{len(context)}.", f"- Mean command execution: {sum(item['elapsed_ms'] for item in results)/max(1,len(results)):.2f} ms; maximum: {max((item['elapsed_ms'] for item in results),default=0):.2f} ms. Mesh checks and screenshots occur separately.", "", "## What changed", "", "- Connected the existing visible assistant to structured native Graph actions, preserving lesson/search/solver routing for educational queries and other workspaces.", "- Added equation plotting, supported solid surface equations, bounded counts, selection, deletion, duplication with a visible offset, material/color/opacity/visibility, grid control, and shared Undo/Redo. Graph command history preserves unrelated fields; selections are separate for 2D and 3D, and failed multi-step history operations leave both stacks unchanged.", "- Compound operations stage immutable snapshots; unsupported or invalid clauses leave the complete scene and history unchanged. Mixed Undo/Redo and mutation batches are rejected explicitly. Preparation runs off the UI thread; a changed workspace prevents a stale commit.", "- Preserved holes at poles and undefined surface regions; only numerically convergent removable holes are filled. Sampling includes diagonal directions. The canvas and audit use the same geometry boundary.", "- Fixed implicit quad triangulation, outward winding, exact-zero edges and duplicate grid-aligned faces. Independent plane coverage and area regressions capture the original failures.", "- Preserved grid preferences on Clear, linked authoritative objects, and semantic references across native primary-layer ID changes.", "- Added saved color appearance, material handling for indexed meshes, and a separate debug-only audit activity.", "- Added persistent object translation, local scaling, orientation and graph groups, including group-centered and world-origin operations. Original sentences lacking numeric arguments request clarification; an explicit-angle compound group edit is tested separately.", "- Added a bounded base-mesh cache and shared visible-scene sampling budget to reduce multi-layer rendering load without dropping layers or changing controls.", "- Bundled a TensorFlow-trained intent model with confidence/margin gates and deterministic parameter validation. No student data or correction records are used for training.", "", "## Limits", "", "The original scope is not fully implemented. Numeric movement, scaling, rotations and grouping are implemented for 3D graph layers. Animation, point/line/vector constructions, many relationship operations, saved-state restoration and unrestricted conversational variants remain unsupported. Graph2D also supports numeric curve translations and quadratic vertex annotations. These 150 cases cover Graph workspaces; the separate shared geometry adapter supports additional native point/shape/solid operations and rotating solids. See [shared architecture report](../ruhi-shared-evidence/REPORT.md). Requests lacking numeric parameters ask for clarification. A passing rejection test establishes safe failure, not feature support. Random sphere placement is repeatable per command for reproducibility. Surface meshes approximate analytic surfaces at bounded resolution. Numerical removable-hole inference is not a symbolic proof of a multivariable limit. Pixel differences establish visible changes, not complete mathematical or visual correctness for every triangle. Symmetry rotations can correctly retain the silhouette while changing triangulation; independent coordinate and orientation tests cover them. Group membership and selection can leave pixels unchanged. Physical GPU performance is unverified.", "", "The primitive convention is mathematical Z-up. Default cube side is 2; sphere parameter is radius; cylinder/cone/pyramid parameter is height. Explicit surfaces use their declared X domain on both grid axes; implicit surfaces use the stored X/Z and Y bounds. The native surface-layer schema does not currently expose three independent spatial domain intervals.", "", "## Reproduction", "", "Run `scripts/run_ruhi_graph_audit.ps1` from the repository root with a connected Android device/emulator. Use `-DeviceSerial emulator-5556` to select a device. Use `-CaseIds 89,144` or `-Category Appearance` to rerun selected device cases. Use `-StateOnly` for JVM state/geometry checks without claiming rendered passes. Open the debug dashboard with `adb shell am start -n com.indianservers.aiexplorer/.GraphAssistantAuditActivity`; it can rerun one case, a category, failures, or the full state/mesh suite. Dashboard mesh results never become rendered passes automatically.", "", "## Failures", ""])
failures = [item for item in results if item["status"] == "FAILED"]
lines.extend([f"- {item['id']}: {item['command']} Expected: {item['expected_parameters']} Actual: {item['message']}; {item['errors']}; pixels={item['changed_pixels']}" for item in failures] or ["None in the recorded run."])
lines.extend(["", "## Unsupported commands", ""])
lines.extend(f"- {item['id']}. {item['command']}" for item in results if item["status"] == "UNSUPPORTED")
lines.extend(["", "## Clarification requested", ""])
lines.extend(f"- {item['id']}. {item['command']} — {item['message']}" for item in results if item["execution"] == "CLARIFICATION")
(args.output / "REPORT.md").write_text("\n".join(lines) + "\n", encoding="utf-8")
rows = "".join(f"<tr data-category='{html.escape(item['category'],quote=True)}'><td>{item['id']}</td><td>{html.escape(item['category'])}</td><td>{html.escape(item['command'])}</td><td>{item['status']}</td><td>{html.escape(item['expected_parameters'])}</td><td>{html.escape(item['message'])}<br>{html.escape(str(item['errors']))}</td><td>{item['rendering']} / {item['changed_pixels']}</td></tr>" for item in results)
options = "".join(f"<option>{html.escape(category)}</option>" for category in categories)
page = f"""<!doctype html><meta charset="utf-8"><title>Ruhi graph audit</title><style>body{{font:15px system-ui;margin:24px;background:#091225;color:#eef4ff}}table{{border-collapse:collapse;width:100%}}td,th{{text-align:left;padding:10px;border:1px solid #41516b}}select,input{{padding:8px;margin:8px}}h1{{font-size:24px}}</style><h1>Ruhi — recorded graph audit</h1><p>{html.escape(str(dict(counts)))}. Pixel results are separate from scene/mesh checks.</p><p>This file displays saved evidence. Use the debug Android dashboard or PowerShell runner to execute tests again.</p><select id="category"><option value="">All categories</option>{options}</select><input id="filter" placeholder="Filter command/status"><table><thead><tr><th>ID</th><th>Category</th><th>Command</th><th>Status</th><th>Expected</th><th>Actual</th><th>Pixels</th></tr></thead><tbody>{rows}</tbody></table><script>function update(){{for(const row of document.querySelectorAll('tbody tr'))row.hidden=(category.value&&row.dataset.category!==category.value)||!row.textContent.toLowerCase().includes(filter.value.toLowerCase());}}category.onchange=update;filter.oninput=update;</script>"""
(args.output / "dashboard.html").write_text(page, encoding="utf-8")
lookup = {item["id"]: item for item in results}
corrections = [{"version":1,"command":command,"intent":intent,"failure_category":category,"root_cause":cause,"expected_result":expected,"verified":lookup.get(case,{}).get("status")=="PASSED","evidence_test_id":case,"administrator_approved_for_training":False,"promoted_to_shared_training":False} for case,command,intent,category,cause,expected in [(89,"Remove the highlight","HIGHLIGHT","NLP","Generic remove handler preceded specific appearance removal","Restore the selected layer's prior color without deleting it"),(144,"Plot z = 1 / (x² + y²)","PLOT","GEOMETRY","Non-finite samples were replaced by nearby averages or zero","Omit cells incident to the pole; retain finite topology"),(119,"Duplicate the selected object","DUPLICATE","RENDERING","An identical overlapping copy cannot establish a visible change","Create a unique layer with the same shape/material and a visible translation")]]
for correction in corrections:
    record=lookup.get(correction["evidence_test_id"],{})
    correction["state_verified"]=bool(record) and not record.get("errors") and record.get("execution")=="APPLIED"
    correction["verification_scope"]="Scene/geometry and central canvas pixel assertion" if correction["verified"] else "Scene/geometry only until a rendering result passes"
topology=args.output/"TEST-com.indianservers.aiexplorer.RuhiImplicitSurfaceTopologyTest.xml"
topology_passed=topology.exists() and int(ET.parse(topology).getroot().get("failures",1))==0 and int(ET.parse(topology).getroot().get("errors",1))==0
corrections.append({"version":1,"command":"Plot y+z=0.13; plot the grid-aligned plane z=0","intent":"PLOT","failure_category":"GEOMETRY","root_cause":"Four edge hits were not cyclically ordered; zero edges introduced extra midpoints and adjacent cells emitted coincident faces","expected_result":"Single coverage, correct plane area, and consistent outward winding","state_verified":topology_passed,"verified":False,"verification_scope":"Independent native mesh tests; rendering pending","administrator_approved_for_training":False,"promoted_to_shared_training":False})
(args.output / "corrections.v1.json").write_text(json.dumps({"model_training_occurred":True,"training_source":"Authored synthetic intent templates, explicitly requested offline TensorFlow training","correction_records_used_for_training":False,"student_data_used_for_training":False,"corrections":corrections},ensure_ascii=False,indent=2),encoding="utf-8")
print(json.dumps(dict(counts)))
